def main():
    if len(sys.argv) != 2:
        sys.stderr.write("usage: python rev33_l2.py <dir>\n")
        return 2
    path = os.path.join(sys.argv[1], "content4.js")
    with open(path, "r", encoding="utf-8", newline="") as fh:
        src = fh.read()
    n = src.count(ANCHOR)
    if n != 1:
        sys.stderr.write("REFUSED: the anchor (the last line of Theorem 8.5's proof) occurs %d times in %s, not once\n" % (n, path))
        return 1
    if GUARD in src:
        sys.stderr.write("REFUSED: %s already holds %s; the insertion is not repeated\n" % (path, GUARD))
        return 1
    for bad in ("${", "\\"):
        if bad in BLOCK:
            sys.stderr.write("REFUSED: the inserted text holds %r\n" % bad)
            return 1
    if BLOCK.count("`") % 2:
        sys.stderr.write("REFUSED: an odd number of backticks in the inserted text\n")
        return 1
    crlf = "\r\n" in src
    i = src.index(ANCHOR)
    j = src.index("\n", i)
    block = BLOCK.replace("\r\n", "\n")
    if crlf:
        block = block.replace("\n", "\r\n")
    new = src[: j + 1] + block + src[j + 1:]
    with open(path, "w", encoding="utf-8", newline="") as fh:
        fh.write(new)
    pushes = block.count("  push(")
    fns = block.count("[[fn:")
    eqs = block.count("push(Eq(")
    sys.stdout.write("rev33_l2: inserted after line %d of %s: %d push calls (%d displays), %d footnotes, %d bytes\n"
                     % (src[:i].count("\n") + 1, path, pushes, eqs, fns, len(block.encode("utf-8"))))
    return 0


if __name__ == "__main__":
    sys.exit(main())
